const fs=require('node:fs'),path=require('node:path');
async function main(){
 const pages=(await(await fetch('http://127.0.0.1:57221/json/list')).json()).filter(t=>t.type==='page'&&t.url.includes('/apps/pc-app/dist/ui/index.html'));if(pages.length!==1)throw Error('Unique original B2 renderer required');
 const expression=`(()=>{if(location.hash!=='#/account')throw Error('Only approved normal account preview route');const rect=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height}};const dialogs=[...document.querySelectorAll('[role=dialog],[role=alertdialog]')].filter(e=>{const r=e.getBoundingClientRect();return r.width&&r.height});return{route:location.hash,visibleText:document.body.innerText.slice(0,22000),dialogs:dialogs.map(d=>({role:d.getAttribute('role'),label:d.getAttribute('aria-label'),text:d.innerText,rect:rect(d),choices:[...d.querySelectorAll('[role=radio],[role=checkbox],input[type=radio],input[type=checkbox],[role=combobox]')].map(e=>({role:e.getAttribute('role'),type:e.getAttribute('type'),label:e.getAttribute('aria-label'),text:e.innerText||e.closest('label')?.innerText||'',checked:e.getAttribute('aria-checked')??(e.matches('input[type=radio],input[type=checkbox]')?e.checked:null),value:e.matches('input[type=radio]')?e.value:null,disabled:e.disabled??null})),buttons:[...d.querySelectorAll('button')].map(e=>({text:e.innerText,label:e.getAttribute('aria-label'),disabled:e.disabled,rect:rect(e)}))})),alerts:[...document.querySelectorAll('[role=alert]')].map(e=>e.innerText),status:[...document.querySelectorAll('[role=status]')].map(e=>e.innerText)}})()`;
 const ws=new WebSocket(pages[0].webSocketDebuggerUrl);const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{ws.close();reject(Error('Readonly timeout'));},10000);ws.onopen=()=>ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{returnByValue:true,expression}}));ws.onerror=()=>{clearTimeout(timer);reject(Error('Readonly connection failed'));};ws.onmessage=e=>{const r=JSON.parse(e.data);if(r.id!==1)return;clearTimeout(timer);ws.close();if(r.error||r.result?.exceptionDetails)reject(Error('Readonly visible preview projection failed'));else resolve(r.result.result.value);};});
 const report={at:new Date().toISOString(),method:'Readonly visible dialog text and standard ARIA/form mode controls only; no private Map/React state/business invocation/input/credential values',previewId:null,previewIdQualification:'Only a publicly visible ID may be recorded; this collector never reads private application state.',result};
 const output=path.join(__dirname,'cloudB2-preview-public-ui-'+process.argv[2]+'-20261026.json');fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({output,...report}));
}main().catch(e=>{console.error(e.message);process.exitCode=1;});
